const std=@import("std");const core=@import("jmcl_core");
pub fn main(init:std.process.Init)!void {const a=init.arena.allocator();const args=try init.minimal.args.toSlice(a);var b:[4096]u8=undefined;var w:std.Io.File.Writer=.init(.stdout(),init.io,&b);var j:std.json.Stringify=.{.writer=&w.interface};run(init,args,&j) catch |e| try j.write(.{.@"error"=@errorName(e)});try w.interface.writeByte('\n');try w.interface.flush();}
fn run(init:std.process.Init,args:[]const []const u8,j:*std.json.Stringify)!void {const a=init.arena.allocator();const b=try std.Io.Dir.cwd().readFileAlloc(init.io,args[2],a,.limited(20*1024*1024));if(std.mem.eql(u8,args[1],"cffile")){const p=try core.curseforge.parseFile(a,b);defer p.deinit();const f=p.value.data;try j.write(.{.id=f.id,.project=f.modId,.name=f.fileName,.sha1=core.curseforge.sha1Of(f.*),.size=f.fileLength,.url=f.downloadUrl});}else if(std.mem.eql(u8,args[1],"cfselect")){const p=try core.curseforge.parseFilesPage(a,b);defer p.deinit();const f=core.curseforge.selectFile(p.value.data);try j.write(if(f) |v| v.id else @as(?u32,null));}else if(std.mem.eql(u8,args[1],"project")){const p=try core.modrinth.parseProject(a,b);defer p.deinit();try j.write(p.value);}else if(std.mem.eql(u8,args[1],"version")){const p=try core.modrinth.parseVersion(a,b);defer p.deinit();try j.write(p.value);}else{const p=try core.modrinth.parseVersions(a,b);defer p.deinit();try j.write(p.value);}}
